#include "VigilX.h"
#include <iostream>
#include <limits>
using namespace std;
VigilX::VigilX():logger(),userManager(logger),resourceManager(logger),threatSimulator(logger),incidentResponse(logger){}
User* VigilX::getCurrentUser() const {if(currentUserID==-1)return nullptr;User* u=userManager.findUserByID(currentUserID);if(!u||!u->isActive())return nullptr;return u;}
void VigilX::login(){if(getCurrentUser()){cout<<"A user is already logged in. Log out first.\n";return;}int id;string username;cout<<"Enter User ID: ";if(!(cin>>id)){cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');cout<<"Invalid input.\n";return;}cin.ignore(numeric_limits<streamsize>::max(),'\n');cout<<"Enter username: ";getline(cin,username);User* u=userManager.findUserByID(id);if(!u||u->getUsername()!=username){cout<<"Login failed.\n";logger.logEvent(username,"Unknown","LOGIN","FAILED");return;}if(!u->isActive()){cout<<"Login failed: inactive user.\n";logger.logEvent(username,u->getRole(),"LOGIN","FAILED_INACTIVE");return;}currentUserID=id;cout<<"Login successful. Welcome, "<<username<<"!\n";logger.logEvent(username,u->getRole(),"LOGIN","SUCCESS");}
void VigilX::logout(){User* u=getCurrentUser();if(!u){currentUserID=-1;cout<<"No active user session.\n";return;}logger.logEvent(u->getUsername(),u->getRole(),"LOGOUT","SUCCESS");cout<<"Logged out successfully.\n";currentUserID=-1;}
void VigilX::viewSession() const {User* u=getCurrentUser();if(!u){cout<<"No active session.\n";return;}u->display();u->displayPermissions();}
void VigilX::accessControl(){User* u=getCurrentUser();if(!u){cout<<"Please log in before requesting access.\n";logger.logEvent("Unauthenticated","Unknown","RESOURCE_ACCESS","DENIED_NOT_AUTHENTICATED");return;}resourceManager.requestAccess(*u);}
void VigilX::run(){int choice;do{cout<<"\n========== VIGILX SECURITY ENGINE ==========\n1. Add User\n2. View Users\n3. Search User\n4. Delete User\n5. Add Resource\n6. View Resources\n7. Search/Delete Resource\n8. Security Logs\n9. Security Statistics\n10. Login\n11. Logout\n12. View Current Session\n13. Request Resource Access\n14. Threat Alerts\n15. Threat Simulator\n16. Incident Response\n0. Exit\n============================================\nEnter choice: ";if(!(cin>>choice)){cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');cout<<"Invalid input.\n";continue;}cin.ignore(numeric_limits<streamsize>::max(),'\n');switch(choice){case 1:userManager.addUser();break;case 2:userManager.viewUsers();break;case 3:userManager.searchUser();break;case 4:userManager.deleteUser();break;case 5:resourceManager.addResource();break;case 6:resourceManager.viewResources();break;case 7:{int sub;cout<<"1. Search Resource\n2. Delete Resource\nChoice: ";if(!(cin>>sub)){cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');cout<<"Invalid input.\n";break;}cin.ignore(numeric_limits<streamsize>::max(),'\n');if(sub==1)resourceManager.searchResource();else if(sub==2)resourceManager.deleteResource();else cout<<"Invalid choice.\n";break;}case 8:logger.viewLogs();break;case 9:logger.viewStatistics();break;case 10:login();break;case 11:logout();break;case 12:viewSession();break;case 13:accessControl();break;case 14:logger.viewThreatAlerts();break;case 15:threatSimulator.runMenu();break;case 16:incidentResponse.runMenu();break;case 0:if(getCurrentUser())logout();cout<<"Exiting VigilX. Goodbye!\n";break;default:cout<<"Invalid choice.\n";}}while(choice!=0);}
